// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund contract with some ether so balance can be checked after selfdestruct
        vm.deal(address(c), 1 ether);

        // Owner calls sudicideAnyone()
        vm.prank(address(this)); // setUp deploys from this contract, so owner is this contract
        c.sudicideAnyone();

        // After selfdestruct, contract balance is 0; after revert, contract still has 1 ether
        assertTrue(address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.prank(nonOwner);
        // The reference contract reverts, buggy one selfdestructs.
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok); // after non-owner call, reference reverts => ok=false; buggy does not revert => ok=true, so this assertion passes only on reference
    }
}
